     "ex": "ALLOW = {\"order_question\": {\"get_order\", \"get_payment\"},\n         \"refund_request\": {\"get_order\", \"get_payment\", \"request_refund\"}}\nNEEDS_APPROVAL = {\"request_refund\"}\nqueue = []\n\ndef guarded_call(task, name, args, tools):\n    if name not in ALLOW[task]:\n        return {\"is_error\": True, \"content\": f\"{name} is not allowed for {task}\"}\n    if name == \"request_refund\" and not 0 < args.get(\"amount\", 0) <= 5000:\n        return {\"is_error\": True, \"content\": \"amount must be between 1 and 5000 EGP\"}\n    if name in NEEDS_APPROVAL:\n        queue.append((name, args))\n        return {\"content\": \"queued for human approval; tell the customer we will confirm within 24 hours\"}\n    return {\"content\": str(tools[name](**args))}\n\ntools = {\"get_order\": lambda order_id: {\"id\": order_id, \"status\": \"late\"}}\nprint(guarded_call(\"order_question\", \"get_order\", {\"order_id\": 1042}, tools))\nprint(guarded_call(\"order_question\", \"request_refund\", {\"order_id\": 1042, \"amount\": 50000}, tools))\nprint(guarded_call(\"refund_request\", \"request_refund\", {\"order_id\": 1042, \"amount\": 50000}, tools))\nprint(guarded_call(\"refund_request\", \"request_refund\", {\"order_id\": 1042, \"amount\": 650}, tools))\nprint(\"queue:\", queue)",
