     "ex": "class Budget:\n    def __init__(self, max_usd, price_in=4.0, price_out=20.0):     # per million tokens; check the pricing page\n        self.max_usd, self.spent = max_usd, 0.0\n        self.price_in, self.price_out = price_in, price_out\n\n    def charge(self, input_tokens, output_tokens):\n        self.spent += input_tokens / 1e6 * self.price_in + output_tokens / 1e6 * self.price_out\n        if self.spent > self.max_usd:\n            raise RuntimeError(f\"cost cap reached: ${self.spent:.3f} > ${self.max_usd}\")\n\nbudget = Budget(max_usd=0.10)\ntry:\n    for step, (i, o) in enumerate([(3000, 400), (6000, 500), (9000, 800), (12000, 900)], start=1):\n        budget.charge(i, o)\n        print(f\"step {step}: spent ${budget.spent:.3f}\")\nexcept RuntimeError as e:\n    print(\"stopped:\", e)",
