     "ex": "import re\n\ntranscript = [\n    {\"role\": \"user\", \"content\": \"My order is late, call me on 01012345678 or mona@example.com\"},\n    {\"role\": \"assistant\", \"content\": [{\"type\": \"tool_use\", \"name\": \"get_order\", \"input\": {\"phone\": \"01012345678\"}}]},\n]\n\ndef redact(obj):\n    if isinstance(obj, str):\n        obj = re.sub(r\"01[0125]\\d{8}\", \"<phone>\", obj)\n        return re.sub(r\"[\\w.+-]+@[\\w-]+\\.[\\w.]+\", \"<email>\", obj)\n    if isinstance(obj, list):\n        return [redact(x) for x in obj]\n    if isinstance(obj, dict):\n        return {k: redact(v) for k, v in obj.items()}\n    return obj\n\nfor msg in redact(transcript):\n    print(msg)",
